for (size_t i = start; i < end; ++i) {
    Particle &pi = particles[i];
    float density = 0.0f;
    const uint32_t cell = pi.cell;
    const int x = static_cast<int>(cell & 0x3FF);
    const int y = static_cast<int>((cell >> 10) & 0x3FF);
    const int z = static_cast<int>((cell >> 20) & 0x3FF);

    for (int dx = -1; dx <= 1; ++dx) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dz = -1; dz <= 1; ++dz) {
                const int nx = x + dx;
                const int ny = y + dy;
                const int nz = z + dz;
                if (nx < 0 || ny < 0 || nz < 0 || nx > 0x3FF || ny > 0x3FF || nz > 0x3FF) continue;
                const uint32_t neighborCell = static_cast<uint32_t>(nx | (ny << 10) | (nz << 20));
                const uint32_t idx = neighborCell % particleCount;
                for (uint32_t j = particleTable[idx]; j != 0xFFFFFFFFu; j = particles[j].next) {
                    const Particle &pj = particles[j];
                    if (pj.cell != neighborCell) continue;
                    const float dx = pi.x - pj.x;
                    const float dy = pi.y - pj.y;
                    const float dz = pi.z - pj.z;
                    const float r2 = dx * dx + dy * dy + dz * dz;
                    if (r2 < h2) {
                        density += mass * poly6 * std::pow(h2 - r2, 3.0f);
                    }
                }
            }
        }
    }
    density += selfDens;
    pi.density = density;
    pi.pressure = gasConstant * (density - restDensity);
}
// END_CODE

